using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Text.RegularExpressions;
using System.Windows.Forms;
using System.Xml.Linq;
using System.Text;
using Microsoft.Web.WebView2.Core;
namespace Shixun {
public sealed partial class ReaderApp {
 async Task<object> Dispatch(string action,Dictionary<string,object> data){string id=S(data,"id");
 if(new[]{"saveAi","aiCredentials","analyze","testAi","clearAi"}.Contains(action))return await AiAction(action,data);
 if(action=="ready"){ready=true;Push();if(arguments.Contains("--background")&&store.State.settings.hiddenStart)window.Hide();if(arguments.Contains("--verify-ui"))Capture();return true;}
 if(action=="sync"){await engine.Run(true,id);return true;}
 if(action=="settings"){var p=ConvertData<Preferences>(data);if(p.interval<1||p.interval>10080||p.retention<1||p.retention>3650||p.duration<3||p.duration>60||!new[]{"system","light","dark"}.Contains(p.theme)||!new[]{"all","filtered"}.Contains(p.notifyScope)||!new[]{"any","all"}.Contains(p.notifyJoin)||!new[]{"custom","system","off"}.Contains(p.notification))throw new SafeError("设置值无效，请检查同步、保留时间和通知选项。");TimeSpan t;if(!TimeSpan.TryParse(p.quietStart,out t)||t.TotalHours<0||t.TotalHours>=24||!TimeSpan.TryParse(p.quietEnd,out t)||t.TotalHours<0||t.TotalHours>=24)throw new SafeError("免打扰时间格式应为 HH:mm。");SetStartup(p.autostart);lock(store.Gate){store.State.settings=p;foreach(var s in store.State.sources.Where(s=>s.interval==0))s.nextRun=Math.Min(s.nextRun,Data.Now()+p.interval*60000d);store.Save();}return true;}
 if(action=="saveSource"){var value=ConvertData<Source>(data);Transport.ValidateUrl(value.url);if(value.name.Length>100||value.group.Length>80||value.interval<0||value.interval>10080)throw new SafeError("名称或同步间隔超出限制。");if(value.imageReferer.Length>0)Transport.ValidateUrl(value.imageReferer);lock(store.Gate){var existing=store.State.sources.FirstOrDefault(s=>s.id==value.id);if(store.State.sources.Any(s=>s.id!=value.id&&s.url==value.url))throw new SafeError("该订阅地址已存在。");if(existing==null){existing=new Source();store.State.sources.Add(existing);}else if(existing.url!=value.url){store.State.credentials.Remove(existing.id);existing.initialized=false;existing.etag="";existing.modified="";}existing.name=Data.Limit(value.name.Trim(),100);existing.url=value.url;existing.group=String.IsNullOrWhiteSpace(value.group)?"我的订阅":value.group;existing.interval=value.interval;existing.enabled=value.enabled;existing.privateSource=value.privateSource||new Uri(value.url).Query.Length>0;existing.imageReferer=value.imageReferer;existing.nextRun=Data.Now()+15000;store.Save();return existing.id;}}
 if(action=="credentials"){lock(store.Gate){bool source=store.State.sources.Any(s=>s.id==id),rule=store.State.ruleSources.Any(s=>s.id==id);if(!source&&!rule)throw new SafeError("来源不存在。");RequestProfile current;store.State.credentials.TryGetValue(id,out current);using(var dialog=new CredentialDialog(current==null?new RequestProfile():Data.Clone(current),source?store.State.sources.First(s=>s.id==id).name:store.State.ruleSources.First(s=>s.id==id).name)){if(dialog.ShowDialog(window)==DialogResult.OK){if(dialog.Result.HasSecrets()||dialog.Result.method!="GET")store.State.credentials[id]=dialog.Result;else store.State.credentials.Remove(id);var item=store.State.sources.FirstOrDefault(s=>s.id==id);if(item!=null){item.etag="";item.modified="";item.nextRun=0;if(dialog.Result.HasSecrets())item.privateSource=true;}store.Save();}}return true;}}
 if(action=="testSource"){Source source;RequestProfile profile;lock(store.Gate){source=Data.Clone(store.State.sources.First(s=>s.id==id));RequestProfile p;profile=store.State.credentials.TryGetValue(id,out p)?Data.Clone(p):new RequestProfile();}return await Task.Run<object>(()=>{var f=Transport.Fetch(source.url,profile);try{var result=Feeds.Parse(f.text,source,f.finalUri);return new{format=result.format,title=result.title,count=result.articles.Count,upstreamUpdated=f.upstreamUpdated,newest=result.articles.Select(a=>a.time).DefaultIfEmpty().Max()};}catch(SafeError){var candidates=Feeds.Discover(f.text,f.finalUri);if(candidates.Count>0)return new{candidates=candidates};throw;}});}
 if(action=="setSourceEnabled"){object raw;if(!data.TryGetValue("enabled",out raw)||!(raw is bool))throw new SafeError("请指定订阅启用状态。");lock(store.Gate){var s=store.State.sources.FirstOrDefault(x=>x.id==id);if(s==null)throw new SafeError("订阅源不存在。");bool enabled=(bool)raw;if(s.enabled!=enabled){s.enabled=enabled;if(enabled)s.nextRun=0;store.Save();}return s.enabled;}}
 if(action=="toggleSource"){lock(store.Gate){var s=store.State.sources.First(x=>x.id==id);s.enabled=!s.enabled;if(s.enabled)s.nextRun=0;store.Save();return s.enabled;}}
 if(action=="deleteSource"){if(!Confirm("删除该订阅源？已经保存的文章仍保留。"))return false;lock(store.Gate){store.State.sources.RemoveAll(s=>s.id==id);store.State.credentials.Remove(id);store.Save();return true;}}
 if(action=="saveCategory"){var c=ConvertData<Category>(data);if(String.IsNullOrWhiteSpace(c.name)||c.name.Length>50||c.keywords.Length>4000||c.exclude.Length>4000||c.pattern.Length>2000||!Regex.IsMatch(c.color,"^#[0-9a-fA-F]{6}$"))throw new SafeError("分类字段无效。");if(c.pattern.Length>0)try{Regex.IsMatch("",c.pattern,RegexOptions.None,TimeSpan.FromMilliseconds(100));}catch{throw new SafeError("正则表达式无效。");}lock(store.Gate){var old=store.State.categories.FirstOrDefault(x=>x.id==c.id);if(old==null){c.id=Data.Id();store.State.categories.Add(c);}else{old.name=c.name;old.color=c.color;old.keywords=c.keywords;old.exclude=c.exclude;old.pattern=c.pattern;old.ruleSource="";old.ruleKey="";}store.Save();return true;}}
 if(action=="deleteCategory"){if(!Confirm("删除分类？文章保留并移到未分类。"))return false;lock(store.Gate){store.State.categories.RemoveAll(c=>c.id==id);foreach(var a in store.State.articles.Where(a=>a.category==id)){a.category="";a.locked=false;}store.State.settings.notifyCategories.Remove(id);store.Save();return true;}}
 if(action=="moveCategory"){lock(store.Gate){int index=store.State.categories.FindIndex(c=>c.id==id);if(index>0){var c=store.State.categories[index];store.State.categories.RemoveAt(index);store.State.categories.Insert(index-1,c);store.Save();}return true;}}
 if(action=="reclassify"){lock(store.Gate){foreach(var a in store.State.articles)a.category=Rules.Classify(store.State,a);store.Save();return true;}}
 if(action=="batchArticles"){lock(store.Gate){object raw;data.TryGetValue("ids",out raw);var ids=raw==null?null:ConvertData<List<string>>(raw);string operation=S(data,"operation"),category=S(data,"category");var items=BatchEdit.Resolve(store.State,ids,operation,category);if(items.Count==0)throw new SafeError("所选内容已经清理。");if(operation=="delete"){if(!Confirm("删除所选 "+items.Count+" 篇内容？不会删除来源原文。"))return false;undoArticles=items.Select(Data.Clone).ToList();undoUntil=Data.Now()+10000;}BatchEdit.Apply(store.State,items,operation,category);store.Save();return items.Count;}}
 if(action=="article"){lock(store.Gate){var a=store.State.articles.FirstOrDefault(x=>x.id==id);if(a==null)throw new SafeError("文章已清理。");string operation=S(data,"operation");if(operation=="read")a.read=true;else if(operation=="unread")a.read=false;else if(operation=="star")a.star=!a.star;else if(operation=="classify"){string category=S(data,"category");if(category.Length>0&&!store.State.categories.Any(c=>c.id==category))throw new SafeError("分类不存在。");a.category=category;a.locked=true;}else if(operation=="delete"){if(!Confirm("删除这条内容？不会删除来源原文。"))return false;store.State.deleted.Add(new Mark{id=id,time=Data.Now()});store.State.articles.Remove(a);undoArticles=new List<Article>{Data.Clone(a)};undoUntil=Data.Now()+10000;}else if(operation=="remind")a.remindAt=Data.Now()+900000;else if(operation=="open"){if(a.link.Length>0)Open(a.link);}else if(operation=="link"){string url=S(data,"url");Uri uri=Transport.ValidateUrl(url);bool allowed=a.link==uri.AbsoluteUri;foreach(Match m in Regex.Matches(a.html,"<a\\b[^>]*?href\\s*=\\s*[\"']([^\"']+)[\"']",RegexOptions.IgnoreCase)){string resolved=Feeds.Resolve(m.Groups[1].Value,new Uri(a.link.Length>0?a.link:store.State.sources.First(s=>s.id==a.source).url));if(resolved==uri.AbsoluteUri)allowed=true;}if(!allowed)throw new SafeError("该链接不是文章中的有效链接。");Open(url);}store.Save();return true;}}
 if(action=="undo"){lock(store.Gate){if(undoArticles==null||Data.Now()>undoUntil)throw new SafeError("撤销时间已过。");BatchEdit.Restore(store.State,undoArticles);undoArticles=null;store.Save();return true;}}
 if(action=="markAllRead"){lock(store.Gate){foreach(var a in store.State.articles.Where(a=>id.Length==0||a.source==id))a.read=true;store.Save();return true;}}
 if(action=="saveRuleSource"){var value=ConvertData<RuleSource>(data);Transport.ValidateUrl(value.url);if(value.name.Length==0||value.name.Length>100)throw new SafeError("请填写规则源名称。");lock(store.Gate){var old=store.State.ruleSources.FirstOrDefault(r=>r.id==value.id);if(old==null){old=new RuleSource();store.State.ruleSources.Add(old);}else if(old.url!=value.url)store.State.credentials.Remove(old.id);old.name=value.name;old.url=value.url;old.autoUpdate=value.autoUpdate;store.Save();return old.id;}}
 if(action=="fetchRules"){var doc=await Task.Run(()=>engine.UpdateRules(id,false));pendingRules[id]=doc;return doc;}
 if(action=="applyRules"){RuleDocument doc;if(!pendingRules.TryGetValue(id,out doc))throw new SafeError("请先获取并预览规则。");lock(store.Gate){Rules.Apply(store.State,doc,id);store.Save();}pendingRules.Remove(id);return true;}
 if(action=="deleteRuleSource"){if(!Confirm("删除规则源配置？已经导入的分类继续保留。"))return false;lock(store.Gate){store.State.ruleSources.RemoveAll(r=>r.id==id);store.State.credentials.Remove(id);pendingRules.Remove(id);store.Save();return true;}}
 if(action=="importRules"){using(var dialog=new OpenFileDialog{Filter="JSON 规则|*.json",CheckFileExists=true}){if(dialog.ShowDialog(window)!=DialogResult.OK)return null;if(new FileInfo(dialog.FileName).Length>1024*1024)throw new SafeError("文件过大。");var doc=Rules.Parse(File.ReadAllText(dialog.FileName,Encoding.UTF8));pendingRules["local-file"]=doc;return doc;}}
 if(action=="exportRules"){RuleDocument doc;lock(store.Gate)doc=new RuleDocument{version=1,categories=store.State.categories.Select(c=>new RuleCategory{key=c.id,name=c.name,color=c.color,keywords=Rules.Words(c.keywords).ToList(),exclude=Rules.Words(c.exclude).ToList()}).ToList()};SaveText("分类规则.json",Data.Json().Serialize(doc),"JSON|*.json");return true;}
 if(action=="exportOpml"){List<Source> sources;lock(store.Gate)sources=store.State.sources.Where(s=>(id.Length==0||s.id==id)&&!s.privateSource&&!store.State.credentials.ContainsKey(s.id)&&new Uri(s.url).Query.Length==0).Select(Data.Clone).ToList();if(sources.Count==0)throw new SafeError("没有可公开导出的订阅。私有来源和带查询参数的地址默认排除。");if(MessageBox.Show(window,"仅导出以下公开来源，不包含凭据。请确认地址路径未包含密钥：\n\n"+String.Join("\n",sources.Select(s=>s.name+"\n"+s.url)),"导出预览",MessageBoxButtons.OKCancel)!=DialogResult.OK)return false;var body=new XElement("body");foreach(var group in sources.GroupBy(s=>s.group)){var folder=new XElement("outline",new XAttribute("text",group.Key));foreach(var s in group)folder.Add(new XElement("outline",new XAttribute("type","rss"),new XAttribute("text",s.name),new XAttribute("xmlUrl",s.url)));body.Add(folder);}SaveText("拾讯订阅.opml",new XDocument(new XElement("opml",new XAttribute("version","2.0"),body)).ToString(),"OPML|*.opml");return true;}
 if(action=="importOpml"){using(var dialog=new OpenFileDialog{Filter="OPML|*.opml;*.xml"}){if(dialog.ShowDialog(window)!=DialogResult.OK)return 0;if(new FileInfo(dialog.FileName).Length>1024*1024)throw new SafeError("文件过大。");var xml=Feeds.Xml(File.ReadAllText(dialog.FileName,Encoding.UTF8));if(xml.Root==null||xml.Root.Name.LocalName!="opml")throw new SafeError("不是 OPML 文件。");var imported=new List<Source>();foreach(var e in xml.Descendants("outline").Where(e=>e.Attribute("xmlUrl")!=null).Take(1000)){string url=(string)e.Attribute("xmlUrl");try{Transport.ValidateUrl(url);}catch{continue;}lock(store.Gate){if(store.State.sources.Any(s=>s.url==url)||imported.Any(s=>s.url==url))continue;}imported.Add(new Source{name=(string)e.Attribute("title")??(string)e.Attribute("text")??"导入订阅",url=url,group=(string)e.Parent.Attribute("text")??"导入订阅",privateSource=true,nextRun=Data.Now()+15000});}if(MessageBox.Show(window,"新增 "+imported.Count+" 个订阅，默认标记为私有，需自行检查公开属性。是否导入？","导入预览",MessageBoxButtons.OKCancel)!=DialogResult.OK)return 0;lock(store.Gate){store.State.sources.AddRange(imported);store.Save();}return imported.Count;}}
 if(action=="backup"){lock(store.Gate){var backup=Data.Clone(store.State);backup.credentials.Clear();backup.ai=new AiSettings();backup.aiDay="";backup.aiRequestsToday=0;backup.sources=backup.sources.Where(s=>!s.privateSource&&!store.State.credentials.ContainsKey(s.id)&&new Uri(s.url).Query.Length==0).ToList();backup.ruleSources.Clear();backup.articles.Clear();backup.seen.Clear();backup.deleted.Clear();backup.notices.Clear();SaveText("拾讯公开配置.json",Data.Json().Serialize(backup),"JSON|*.json");return true;}}
 if(action=="restore"){using(var dialog=new OpenFileDialog{Filter="JSON 配置|*.json"}){if(dialog.ShowDialog(window)!=DialogResult.OK)return false;if(new FileInfo(dialog.FileName).Length>2*1024*1024)throw new SafeError("备份文件过大。");var imported=Data.Json().Deserialize<ClientState>(File.ReadAllText(dialog.FileName));if(imported==null||imported.version!=1||imported.sources==null||imported.categories==null||imported.sources.Count>1000||imported.categories.Count>1000)throw new SafeError("备份格式无效。");foreach(var s in imported.sources)Transport.ValidateUrl(s.url);if(MessageBox.Show(window,"将合并公开来源与分类，不导入凭据、文章和系统自启。继续？","恢复预览",MessageBoxButtons.OKCancel)!=DialogResult.OK)return false;lock(store.Gate){foreach(var s in imported.sources.Where(s=>!store.State.sources.Any(x=>x.url==s.url))){s.id=Data.Id();s.privateSource=true;s.initialized=false;store.State.sources.Add(s);}foreach(var c in imported.categories){c.id=Data.Id();c.ruleSource="";store.State.categories.Add(c);}store.Save();}return true;}}
 if(action=="clean"){store.Clean();return true;}
 if(action=="testNotify"){Article sample;lock(store.Gate)sample=store.State.articles.FirstOrDefault();if(sample==null)sample=new Article{id="sample",title="拾讯已准备好，等下一条好发现",summary="这是通知样式预览。添加订阅后，新内容将在这里提醒你。"};Notify(new List<Article>{sample},true);return true;}
 if(action=="pauseNotify"){pauseUntil=Data.Now()+900000;return true;}
 if(action=="migrate"){using(var dialog=new FolderBrowserDialog{Description="选择旧客户端所在目录（含 config.json）"}){if(dialog.ShowDialog(window)==DialogResult.OK)Migrate(dialog.SelectedPath);}return true;}
 if(action=="copy"){string text=S(data,"text");if(text.Length>100000)throw new SafeError("复制内容过长。");Clipboard.SetText(text);return true;}
 if(action=="exit"){ExitThread();return true;}
 throw new SafeError("未支持的操作。");
 }
 List<Article> undoArticles;double undoUntil;
 bool Confirm(string message){return !store.State.settings.confirmDelete||MessageBox.Show(window,message,"请确认删除",MessageBoxButtons.OKCancel,MessageBoxIcon.Question)==DialogResult.OK;}
 void SaveText(string filename,string text,string filter){using(var dialog=new SaveFileDialog{FileName=filename,Filter=filter,OverwritePrompt=true})if(dialog.ShowDialog(window)==DialogResult.OK)File.WriteAllText(dialog.FileName,text,new UTF8Encoding(false));}
 void SetStartup(bool enabled){string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Startup),"Shixun.lnk");if(enabled){Type type=Type.GetTypeFromProgID("WScript.Shell");dynamic shell=Activator.CreateInstance(type);dynamic shortcut=shell.CreateShortcut(path);shortcut.TargetPath=Path.Combine(root,"Shixun.exe");shortcut.Arguments="--background";shortcut.WorkingDirectory=root;shortcut.Save();System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shortcut);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(shell);}else if(File.Exists(path))File.Delete(path);}
 async void Capture(){try{await Task.Delay(2000);await web.ExecuteScriptAsync("document.querySelector('.article')?.click()");await Task.Delay(5000);string report=await web.ExecuteScriptAsync("JSON.stringify({heading:document.querySelector('h1').textContent,settings:!!document.querySelector('#settingsButton'),native:!!window.chrome.webview,articles:document.querySelectorAll('.article').length,imagesLoaded:[...document.querySelectorAll('img')].filter(i=>i.complete&&i.naturalWidth>0).length,bodyLinks:document.querySelectorAll('.body a').length,titleHeight:document.querySelector('.article-title')?.getBoundingClientRect().height||0,bodyTop:document.querySelector('.body')?.getBoundingClientRect().top||0,topOriginal:!!document.querySelector('.detail-top .open-original'),aiSettings:!!document.querySelector('#settingsNavigation')})");File.WriteAllText(Path.Combine(store.Folder,"ui-check.json"),Data.Json().Deserialize<string>(report));using(var stream=File.Create(Path.Combine(store.Folder,"ui-preview.png")))await web.CoreWebView2.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);}catch{store.Log("UI capture failed");}}
}
}
